public class ClassX {
    /**
     * Εξάγει ένα συγκεκριμένο μέλος από ένα αρχείο (προσομοίωση).
     * 
     * Η συνάρτηση ελέγχει αν το όνομα του μέλους αρχίζει με μια κάθετο για να αποτρέψει απόλυτες διαδρομές.
     * 
     * @param memberName το όνομα του μέλους
     * @param filePath η διαδρομή του αρχείου
     * @return το περιεχόμενο του μέλους
     * @throws IOException σε περίπτωση σφάλματος κατά την ανάγνωση του αρχείου
     */
    public String extractMember(String memberName, String filePath) throws IOException {
        if (memberName.startsWith("/")) {
            throw new IllegalArgumentException("Απαγορεύεται η χρήση απόλυτων διαδρομών.");
        }

        StringBuilder memberContent = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            boolean memberFound = false;

            while ((line = reader.readLine()) != null) {
                if (line.contains(memberName)) {
                    memberFound = true;
                }
                if (memberFound) {
                    memberContent.append(line).append(System.lineSeparator());
                    // Assuming that the member ends with a specific delimiter, e.g., a blank line.
                    if (line.trim().isEmpty()) {
                        break;
                    }
                }
            }
        }

        return memberContent.toString().trim();
    }
}
