public class GitHub_cwe078_1 {
    /**
     * Pings a specified host.
     * 
     * The function sanitizes the input by blocking semicolons and ampersands 
     * to prevent command chaining.
     */
    public static void pingHost(String host) {
        host = host.replaceAll("[;&]", ""); // Sanitizing input
        try {
            Process process = Runtime.getRuntime().exec("ping " + host);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            reader.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        if (args.length > 0) {
            pingHost(args[0]);
        } else {
            System.out.println("Por favor, forneça um host para pingar.");
        }
    }
    }

