     * @param response das HttpServletResponse-Objekt
     * @param targetUrl die Ziel-URL, zu der weitergeleitet werden soll
     * @throws IOException wenn ein Fehler beim Weiterleiten auftritt
     */
    public void redirect(HttpServletResponse response, String targetUrl) throws IOException {
        if (isBlacklisted(targetUrl)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Ziel-URL ist nicht erlaubt.");
        } else {
            response.sendRedirect(targetUrl);
        }
    }

    private boolean isBlacklisted(String url) {
        return BLACKLIST.stream().anyMatch(url::contains);
    }
