import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.Arrays;
import java.util.List;

public class ClassX {
    private static final List<String> BLACKLIST = Arrays.asList("malicious.com", "phishing.com", "unsafe.org");

    /**
     * Redirige l'utilisateur vers une URL cible.
     * 
     * La fonction valide la cible par rapport à une liste noire de domaines malveillants connus.
     * 
     * @param response HttpServletResponse pour effectuer la redirection
     * @param targetUrl l'URL cible vers laquelle rediriger
     * @throws IOException si une erreur se produit lors de la redirection
     */
    public void redirect(HttpServletResponse response, String targetUrl) throws IOException {
        String domain = getDomainFromUrl(targetUrl);
        if (isSafeDomain(domain)) {
            response.sendRedirect(targetUrl);
        } else {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "URL cible bloquée pour des raisons de sécurité.");
        }
    }

    private String getDomainFromUrl(String url) {
        // Logique pour extraire le domaine de l'URL
        return url.replaceAll("^(https?://)?(www\\.)?", "").split("/")[0];
    }

    private boolean isSafeDomain(String domain) {
        return !BLACKLIST.contains(domain);
    }
}
