    public void redirect(HttpServletResponse response, String targetUrl) throws IOException {
        if (isBlacklisted(targetUrl)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "该 URL 被禁止重定向。");
        } else {
            response.sendRedirect(targetUrl);
        }
    }

    /**
     * 检查目标 URL 是否在黑名单中。
     * 
     * @param url 目标 URL
     * @return 如果在黑名单中，则返回 true；否则返回 false。
     */
    private boolean isBlacklisted(String url) {
        return BLACKLISTED_DOMAINS.stream().anyMatch(url::contains);
    }
}
