     * @throws IOException nếu có lỗi xảy ra trong quá trình chuyển hướng
     */
    public void redirect(HttpServletResponse response, String targetUrl) throws IOException {
        String domain = extractDomain(targetUrl);
        if (isDomainBlacklisted(domain)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Domain is blacklisted.");
        } else {
            response.sendRedirect(targetUrl);
        }
