import java.net.HttpURLConnection;
import java.net.URL;
import java.net.URLEncoder;

public class ClassX {
    /**
     * Hakee sisältöä luodusta URL-osoitteesta isäntää validoimalla.
     * 
     * Tämä toiminto puhdistaa isännän tarkistamalla virheelliset merkit, kuten välilyönnit.
     * 
     * @param urlString URL-osoite, josta sisältö haetaan.
     * @return Sisältö URL-osoitteesta.
     * @throws Exception mahdolliset poikkeukset.
     */
    public String fetchContent(String urlString) throws Exception {
        // Puhdistetaan URL-osoite
        String cleanedUrlString = urlString.trim();
        if (!isValidHost(cleanedUrlString)) {
            throw new IllegalArgumentException("Virheellinen isäntä: " + cleanedUrlString);
        }

        URL url = new URL(cleanedUrlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String inputLine;

        while ((inputLine = in.readLine()) != null) {
            content.append(inputLine);
        }
        in.close();
        return content.toString();
