import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;

public class ClassX {
    /**
     * Busca conteúdo de uma URL gerada após validar o host.
     * 
     * Esta função sanitiza o host verificando a presença de caracteres inválidos, como espaços.
     * 
     * @param host O host a ser validado e utilizado na URL.
     * @return O conteúdo da URL como uma String, ou null se houver erro.
     */
    public String fetchContent(String host) {
        if (host == null || host.trim().isEmpty() || host.contains(" ")) {
            throw new IllegalArgumentException("Host inválido.");
        }

        StringBuilder content = new StringBuilder();
        try {
            URL url = new URL("http://" + host);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }
            in.close();
        } catch (MalformedURLException e) {
            System.err.println("URL malformada: " + e.getMessage());
            return null;
        } catch (Exception e) {
            System.err.println("Erro ao buscar conteúdo: " + e.getMessage());
            return null;
        }

        return content.toString();
    }
}
