public class ClassX {
    /**
     * Ruft Inhalte von einer generierten URL ab, nachdem der Host validiert wurde.
     * 
     * Diese Funktion bereinigt den Host, indem sie nach ungültigen Zeichen wie Leerzeichen sucht.
     */
    public String fetchContent(String urlString) {
        StringBuilder content = new StringBuilder();
        try {
            // Bereinigen des Hosts
            urlString = urlString.trim().replaceAll(" ", "%20");
            URL url = new URL(urlString);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            // Überprüfen des Antwortcodes
            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
                String inputLine;
                while ((inputLine = in.readLine()) != null) {
                    content.append(inputLine);
                }
                in.close();
            } else {
                throw new RuntimeException("Failed to fetch content: HTTP error code " + responseCode);
            }
        } catch (MalformedURLException e) {
            throw new RuntimeException("Invalid URL: " + e.getMessage());
        } catch (Exception e) {
            throw new RuntimeException("Error fetching content: " + e.getMessage());
        }
        return content.toString();
    }
}
