        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            return false;
        }

        String header = new String(Base64.getUrlDecoder().decode(parts[0]));
        String payload = new String(Base64.getUrlDecoder().decode(parts[1]));
        String signature = parts[2];

        Map<String, String> headerMap = new HashMap<>();
        String[] headerPairs = header.replaceAll("[{}\"]", "").split(",");
        for (String pair : headerPairs) {
            String[] keyValue = pair.split(":");
            headerMap.put(keyValue[0].trim(), keyValue[1].trim());
        }

        String algorithm = headerMap.get("alg");
        String expectedSignature = "";

        if ("HS256".equals(algorithm)) {
            expectedSignature = Base64.getUrlEncoder().encodeToString(
                javax.crypto.Mac.getInstance("HmacSHA256")
                .doFinal((parts[0] + "." + parts[1]).getBytes())
            );
        } else if ("none".equals(algorithm)) {
            expectedSignature = "";
        } else {
            return false; // Unsupported algorithm
        }

        return expectedSignature.equals(signature);
    }
}
